import mongoose from 'mongoose';

export const ISSUE_STATUSES = [
  'backlog',
  'todo',
  'in_progress',
  'in_review',
  'done',
  'canceled',
];

export const ISSUE_PRIORITIES = ['no_priority', 'low', 'medium', 'high', 'urgent'];

const issueSchema = new mongoose.Schema(
  {
    /**
     * Human readable unique id in the form TEAM_KEY-NUMBER (ENG-1, DES-2, ...).
     * Generated by the issue controller when the issue is created.
     */
    identifier: {
      type: String,
      required: true,
      unique: true,
      index: true,
    },
    title: {
      type: String,
      required: [true, 'Title is required'],
      trim: true,
    },
    description: {
      type: String,
      default: '',
    },
    status: {
      type: String,
      enum: ISSUE_STATUSES,
      default: 'todo',
    },
    priority: {
      type: String,
      enum: ISSUE_PRIORITIES,
      default: 'no_priority',
    },
    team: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Team',
      required: true,
      index: true,
    },
    assignee: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      default: null,
    },
    creator: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: true,
    },
    /**
     * Parent-child link. null for top level issues, an Issue _id for sub-issues.
     */
    parentIssue: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Issue',
      default: null,
      index: true,
    },
    labels: {
      type: [String],
      default: [],
    },
  },
  { timestamps: true }
);

const Issue = mongoose.model('Issue', issueSchema);

export default Issue;
